    /// <summary>Builds the initial state (tick 0, empty log). Does not apply commands.</summary>
    public static SimState loadScenario(Scenario scenario)
    {
        var height = scenario.map.length;
        var width = scenario.map[Js.Idx(0)]?.length ?? 0;
        if ((height == 0) || (width == 0))
        {
            throw new Exception("loadScenario: map is empty");
        }
        var state = States.createState(new() { seed = scenario.seed, width = Js.I(width), height = Js.I(height) });
        scenario.map.forEach((row, y) =>
        {
            if (row.length != width)
            {
                throw new Exception($"loadScenario: row {Js.Str(y)} has length {Js.Str(row.length)}, expected {Js.Str(width)}");
            }
            (row).ToList().forEach((@char, x) =>
        {
            if (Js.T(placeEntity(state, @char, x, y)))
            {
                return;
            }
            var tile = CHAR_TILES[Js.Idx(@char)];
            if (tile == null)
            {
                throw new Exception($"loadScenario: unknown char '{Js.Str(@char)}' at ({Js.Str(x)}, {Js.Str(y)})");
            }
            Grids.setTile(state.grid, x, y, tile);
        });
        });
        var EDGE_KINDS = new() { wall = Grids.EDGE_WALL, door = Grids.EDGE_DOOR, barricade = 3, window = 4, brokenWindow = 5 };
        foreach (var e in Js.Iter(scenario.edges ?? []))
        {
            Grids.setEdge(state.grid, e.x, e.y, e.side, EDGE_KINDS[Js.Idx(e.kind)]);
        }
        foreach (var room in Js.Iter(scenario.rooms ?? []))
        {
            state.roomDesignations.push(new() { id = $"r{Js.Str(state.nextId++)}", x = Js.I(room.x), y = Js.I(room.y), purpose = room.purpose });
        }
        return state;
    }

    /// <summary>Loads the scenario and replays its command log up to `ticks`.</summary>
    public static SimState runScenario(Scenario scenario, double ticks)
    {
        return Replay.replay(loadScenario(scenario), scenario.commands ?? [], ticks);
    }
